From 6bcfd41765f0ae63c58591361ca795814c434a9b Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 22:16:19 +0100
Subject: [PATCH] plasmoid: highlight the screen layout that matches the
 current setup

The applet's layout buttons never showed which one was in use, so users
could not tell whether their screens were mirrored or extended. Check the
current configuration against each preset and mark the matching button.

BUG: 469366
---
 common/osdaction.cpp               | 48 +++++++++++++++++++++++++-----
 common/osdaction.h                 |  1 +
 plasmoid/ScreenLayoutSelection.qml |  2 ++
 plasmoid/kscreenapplet.cpp         | 11 +++++++
 plasmoid/kscreenapplet.h           |  7 +++++
 5 files changed, 62 insertions(+), 7 deletions(-)

diff --git a/common/osdaction.cpp b/common/osdaction.cpp
index 0f41f2f9..40af12d3 100644
--- a/common/osdaction.cpp
+++ b/common/osdaction.cpp
@@ -33,14 +33,8 @@ QList<OsdAction> OsdAction::availableActions()
     };
 }

-KScreen::SetConfigOperation *OsdAction::applyAction(const QSharedPointer<KScreen::Config> &config, Action action)
+static std::pair<OutputPtr, OutputPtr> internalAndExternal(const OutputList &outputs)
 {
-    const ConfigPtr copy = config->clone();
-    const OutputList outputs = copy->connectedOutputs();
-    if (outputs.size() != 2) {
-        return nullptr;
-    }
-
     auto internalIt = std::find_if(outputs.cbegin(), outputs.cend(), [](const auto &output) {
         return output->type() == KScreen::Output::Type::Panel;
     });
@@ -51,6 +45,46 @@ KScreen::SetConfigOperation *OsdAction::applyAction(const QSharedPointer<KScreen
     const OutputPtr &external = *std::find_if(outputs.cbegin(), outputs.cend(), [&internal](const auto &output) {
         return output != internal;
     });
+    return {internal, external};
+}
+
+OsdAction::Action OsdAction::currentAction(const QSharedPointer<KScreen::Config> &config)
+{
+    const OutputList outputs = config->connectedOutputs();
+    if (outputs.size() != 2) {
+        return NoAction;
+    }
+    const auto [internal, external] = internalAndExternal(outputs);
+
+    if (internal->isEnabled() && !external->isEnabled()) {
+        return SwitchToInternal;
+    }
+    if (!internal->isEnabled() && external->isEnabled()) {
+        return SwitchToExternal;
+    }
+    if (!internal->isEnabled() || !external->isEnabled()) {
+        return NoAction;
+    }
+    if (external->replicationSource() == internal->id() || internal->replicationSource() == external->id() || internal->pos() == external->pos()) {
+        return Clone;
+    }
+    if (external->pos().x() == internal->pos().x() + config->logicalSizeForOutputInt(*internal).width()) {
+        return ExtendRight;
+    }
+    if (internal->pos().x() == external->pos().x() + config->logicalSizeForOutputInt(*external).width()) {
+        return ExtendLeft;
+    }
+    return NoAction;
+}
+
+KScreen::SetConfigOperation *OsdAction::applyAction(const QSharedPointer<KScreen::Config> &config, Action action)
+{
+    const ConfigPtr copy = config->clone();
+    const OutputList outputs = copy->connectedOutputs();
+    if (outputs.size() != 2) {
+        return nullptr;
+    }
+    const auto [internal, external] = internalAndExternal(outputs);

     external->setReplicationSource(0);
     internal->setReplicationSource(0);
diff --git a/common/osdaction.h b/common/osdaction.h
index 1668fb48..8097ab6b 100644
--- a/common/osdaction.h
+++ b/common/osdaction.h
@@ -43,6 +43,7 @@ public:
     QString iconName;

     static QList<OsdAction> availableActions();
+    static Action currentAction(const QSharedPointer<KScreen::Config> &config);
     static KScreen::SetConfigOperation *applyAction(const QSharedPointer<KScreen::Config> &config, Action action);
 };

diff --git a/plasmoid/ScreenLayoutSelection.qml b/plasmoid/ScreenLayoutSelection.qml
