diff --git a/plasmoid/kscreenapplet.cpp b/plasmoid/kscreenapplet.cpp
index b48b785d..24b1da46 100644
--- a/plasmoid/kscreenapplet.cpp
+++ b/plasmoid/kscreenapplet.cpp
@@ -48,6 +48,11 @@ int KScreenApplet::connectedOutputCount() const
     return m_connectedOutputCount;
 }

+KScreen::OsdAction::Action KScreenApplet::currentLayoutPreset() const
+{
+    return m_currentLayoutPreset;
+}
+
 void KScreenApplet::applyLayoutPreset(KScreen::OsdAction::Action action)
 {
     KScreen::OsdAction::applyAction(m_screenConfiguration, action);
@@ -69,6 +74,12 @@ void KScreenApplet::checkOutputs()
     if (m_connectedOutputCount != oldConnectedOutputCount) {
         emit connectedOutputCountChanged();
     }
+
+    const auto currentLayoutPreset = KScreen::OsdAction::currentAction(m_screenConfiguration);
+    if (currentLayoutPreset != m_currentLayoutPreset) {
+        m_currentLayoutPreset = currentLayoutPreset;
+        Q_EMIT currentLayoutPresetChanged();
+    }
 }

 QVariant KScreenApplet::availableActions()
diff --git a/plasmoid/kscreenapplet.h b/plasmoid/kscreenapplet.h
index fc5b2a0e..3332abca 100644
--- a/plasmoid/kscreenapplet.h
+++ b/plasmoid/kscreenapplet.h
@@ -30,6 +30,10 @@ class KScreenApplet : public Plasma::Applet
      * The number of currently connected (not necessarily enabled) outputs
      */
     Q_PROPERTY(int connectedOutputCount READ connectedOutputCount NOTIFY connectedOutputCountChanged FINAL)
+    /**
+     * The layout preset matching the current screen setup, if any
+     */
+    Q_PROPERTY(KScreen::OsdAction::Action currentLayoutPreset READ currentLayoutPreset NOTIFY currentLayoutPresetChanged FINAL)
     Q_PROPERTY(QVariant availableActions READ availableActions CONSTANT STORED false FINAL)

 public:
@@ -39,6 +43,7 @@ public:
     void init() override;

     int connectedOutputCount() const;
+    KScreen::OsdAction::Action currentLayoutPreset() const;

     Q_INVOKABLE void applyLayoutPreset(KScreen::OsdAction::Action action);

@@ -46,10 +51,12 @@ public:

 Q_SIGNALS:
     void connectedOutputCountChanged();
+    void currentLayoutPresetChanged();

 private:
     void checkOutputs();

     KScreen::ConfigPtr m_screenConfiguration;
     int m_connectedOutputCount = 0;
+    KScreen::OsdAction::Action m_currentLayoutPreset = KScreen::OsdAction::NoAction;
 };
